-- Crew Admin Pagination Phase 2. These projections page at the database boundary;
-- existing mutation and lifecycle authorities remain the single source of truth.

create or replace function public.crew_attendance_admin_page(
  p_from date, p_to date, p_outlet_id uuid default null,
  p_filters jsonb default '{}'::jsonb, p_page integer default 1, p_page_size integer default 20
) returns jsonb language plpgsql stable security definer set search_path=public as $$
declare v_page integer:=greatest(coalesce(p_page,1),1); v_size integer:=case when p_page_size in (20,50,100) then p_page_size else 20 end;
  v_offset integer; v_total integer; v_rows jsonb; v_summary jsonb; v_options jsonb;
begin
  if not public.current_user_has_permission('crew_attendance.view') then raise exception using errcode='42501',message='Attendance permission is required.'; end if;
  if p_from is null or p_to is null or p_to<p_from or p_to-p_from>366 then raise exception using errcode='22023',message='Attendance date range must be 367 days or fewer.'; end if;
  if p_outlet_id is not null and not public.current_user_can_access_outlet(p_outlet_id) then raise exception using errcode='42501',message='Attendance is outside your outlet scope.'; end if;
  v_offset:=(v_page-1)*v_size;
  with base as materialized (
    select a.*,jsonb_build_object('id',e.id,'full_name',e.full_name,'nickname',e.nickname,'position',e.position,'workplace',e.workplace) employee,
      jsonb_build_object('id',o.id,'name',o.name) outlet,s.schedule,
      case when s.schedule is null then 'no_roster' when s.schedule->>'entry_type'<>'working' then 'not_required' when a.status='open' then 'open' else 'completed' end roster_evidence_state,
      case when s.schedule is not null and s.schedule->>'entry_type'='working' and s.schedule->>'start_time' is not null then round(extract(epoch from (a.clock_in_at-(((s.schedule->>'date')::date+(s.schedule->>'start_time')::time) at time zone 'Asia/Kuala_Lumpur')))/60)::integer else null end clock_in_variance_minutes,
      'roster-attendance-evidence-v1' evidence_version
    from public.crew_attendance_records a join public.employees e on e.id=a.employee_id left join public.outlets o on o.id=a.outlet_id
    left join lateral(select public.crew_roster_employee_day(a.employee_id,timezone('Asia/Kuala_Lumpur',a.clock_in_at)::date) schedule)s on true
    where timezone('Asia/Kuala_Lumpur',a.clock_in_at)::date between p_from and p_to and (p_outlet_id is null or a.outlet_id=p_outlet_id) and public.current_user_can_access_outlet(a.outlet_id)
  ), filtered as materialized (
    select * from base b where (coalesce(p_filters->>'employee_id','all')='all' or b.employee_id=(p_filters->>'employee_id')::uuid)
      and (coalesce(p_filters->>'position','all')='all' or b.employee->>'position'=p_filters->>'position')
      and (coalesce(p_filters->>'status','all')='all'
        or (p_filters->>'status'='verified' and b.clock_in_location_verified and (b.clock_out_at is null or b.clock_out_location_verified))
        or (p_filters->>'status'='variance' and coalesce(b.clock_in_variance_minutes,0)<>0)
        or (p_filters->>'status'='location_exception' and (b.clock_in_location_exception or b.clock_out_location_exception))
        or (p_filters->>'status'='incomplete' and b.schedule is not null and b.schedule->>'entry_type'='working' and b.status<>'completed')
        or (p_filters->>'status'='no_roster' and b.schedule is null))
  )
  select count(*) into v_total from filtered;
  with base as materialized (
    select a.*,jsonb_build_object('id',e.id,'full_name',e.full_name,'nickname',e.nickname,'position',e.position,'workplace',e.workplace) employee,jsonb_build_object('id',o.id,'name',o.name) outlet,s.schedule,
      case when s.schedule is null then 'no_roster' when s.schedule->>'entry_type'<>'working' then 'not_required' when a.status='open' then 'open' else 'completed' end roster_evidence_state,
      case when s.schedule is not null and s.schedule->>'entry_type'='working' and s.schedule->>'start_time' is not null then round(extract(epoch from (a.clock_in_at-(((s.schedule->>'date')::date+(s.schedule->>'start_time')::time) at time zone 'Asia/Kuala_Lumpur')))/60)::integer else null end clock_in_variance_minutes,'roster-attendance-evidence-v1' evidence_version
    from public.crew_attendance_records a join public.employees e on e.id=a.employee_id left join public.outlets o on o.id=a.outlet_id left join lateral(select public.crew_roster_employee_day(a.employee_id,timezone('Asia/Kuala_Lumpur',a.clock_in_at)::date) schedule)s on true
    where timezone('Asia/Kuala_Lumpur',a.clock_in_at)::date between p_from and p_to and (p_outlet_id is null or a.outlet_id=p_outlet_id) and public.current_user_can_access_outlet(a.outlet_id)
  ), filtered as (
    select * from base b where (coalesce(p_filters->>'employee_id','all')='all' or b.employee_id=(p_filters->>'employee_id')::uuid) and (coalesce(p_filters->>'position','all')='all' or b.employee->>'position'=p_filters->>'position') and (coalesce(p_filters->>'status','all')='all' or (p_filters->>'status'='verified' and b.clock_in_location_verified and (b.clock_out_at is null or b.clock_out_location_verified)) or (p_filters->>'status'='variance' and coalesce(b.clock_in_variance_minutes,0)<>0) or (p_filters->>'status'='location_exception' and (b.clock_in_location_exception or b.clock_out_location_exception)) or (p_filters->>'status'='incomplete' and b.schedule is not null and b.schedule->>'entry_type'='working' and b.status<>'completed') or (p_filters->>'status'='no_roster' and b.schedule is null))
  ) select coalesce(jsonb_agg(to_jsonb(x) order by x.clock_in_at desc,x.id desc),'[]'::jsonb) into v_rows from (select * from filtered order by clock_in_at desc,id desc offset v_offset limit v_size)x;
  select jsonb_build_object('present',count(distinct value->'employee'->>'id') filter(where value->>'clock_in_at' is not null),'variance',count(*) filter(where coalesce((value->>'clock_in_variance_minutes')::integer,0)<>0),'exceptions',count(*) filter(where coalesce((value->>'clock_in_location_exception')::boolean,false) or coalesce((value->>'clock_out_location_exception')::boolean,false)),'incomplete',count(*) filter(where value->'schedule' is not null and value->'schedule'->>'entry_type'='working' and value->>'status'<>'completed'),'non_working',count(*) filter(where value->'schedule' is not null and value->'schedule'->>'entry_type'<>'working'),'no_roster',count(*) filter(where value->'schedule' is null or value->'schedule'='null'::jsonb),'large_variance',count(*) filter(where abs(coalesce((value->>'clock_in_variance_minutes')::integer,0))>=30)) into v_summary from jsonb_array_elements(public.crew_attendance_admin_with_roster(p_from,p_to,p_outlet_id));
  select jsonb_build_object('employees',coalesce(jsonb_agg(distinct value->'employee'),'[]'::jsonb),'positions',coalesce(jsonb_agg(distinct value->'employee'->>'position') filter(where value->'employee'->>'position' is not null),'[]'::jsonb)) into v_options from jsonb_array_elements(public.crew_attendance_admin_with_roster(p_from,p_to,p_outlet_id));
  return jsonb_build_object('rows',v_rows,'total_count',v_total,'page',v_page,'page_size',v_size,'summary',v_summary || jsonb_build_object('filter_options',v_options));
end; $$;
revoke all on function public.crew_attendance_admin_page(date,date,uuid,jsonb,integer,integer) from public,anon,authenticated;
grant execute on function public.crew_attendance_admin_page(date,date,uuid,jsonb,integer,integer) to authenticated;

create or replace function public.crew_cash_admin_page(p_outlet_id uuid,p_from date,p_to date,p_listing text default 'checkouts',p_page integer default 1,p_page_size integer default 20)
returns jsonb language plpgsql stable security definer set search_path=public as $$
declare v_page integer:=greatest(coalesce(p_page,1),1); v_size integer:=case when p_page_size in(20,50,100) then p_page_size else 20 end; v_total integer; v_rows jsonb; v_summary jsonb; v_settings jsonb; v_collections jsonb;
begin
 if not ((public.current_user_has_permission('crew_cash_checkout.view') or public.current_user_has_permission('crew_cash_deposit.view')) and public.current_user_can_access_outlet(p_outlet_id)) then raise exception using errcode='42501',message='Cash Checkout access is unavailable for this outlet.'; end if;
 if p_from is null or p_to is null or p_to<p_from or p_to-p_from>366 then raise exception using errcode='22023',message='Cash Checkout date range must be 367 days or fewer.'; end if;
 if p_listing not in ('checkouts','ledger') then raise exception using errcode='22023',message='Unsupported Cash Checkout listing.'; end if;
 select coalesce(to_jsonb(s),'{}'::jsonb) into v_settings from public.crew_cash_settings s where s.outlet_id=p_outlet_id;
 select jsonb_build_object('current_balance',coalesce(sum(signed_amount),0),'available_balance',public.crew_cash_available_balance(p_outlet_id),'total_added',coalesce(sum(greatest(signed_amount,0)),0),'total_collected',coalesce(sum(greatest(-signed_amount,0)),0),'pending_handover',coalesce((select sum(amount) from public.crew_cash_collections where outlet_id=p_outlet_id and status='pending_receipt'),0)) into v_summary from public.crew_cash_ledger_entries where outlet_id=p_outlet_id;
 select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc),'[]'::jsonb) into v_collections from (select c.*,coalesce(r.full_name,c.external_receiver_name) receiver_name from public.crew_cash_collections c left join public.employees r on r.id=c.receiver_employee_id where c.outlet_id=p_outlet_id and c.status in ('pending_receipt','review_required'))x;
 if p_listing='checkouts' then
  select count(*) into v_total from public.crew_cash_checkouts where outlet_id=p_outlet_id and business_date between p_from and p_to;
  select coalesce(jsonb_agg(to_jsonb(x) order by x.business_date desc,x.id desc),'[]'::jsonb) into v_rows from (select c.*,e.full_name checked_out_by from public.crew_cash_checkouts c join public.employees e on e.id=c.checked_out_by_employee_id where c.outlet_id=p_outlet_id and c.business_date between p_from and p_to order by c.business_date desc,c.id desc offset (v_page-1)*v_size limit v_size)x;
 else
  select count(*) into v_total from public.crew_cash_ledger_entries l where l.outlet_id=p_outlet_id and timezone('Asia/Kuala_Lumpur',l.occurred_at)::date between p_from and p_to;
  with ledger as (select l.id,l.occurred_at,l.entry_type,l.activity,greatest(l.signed_amount,0) amount_in,greatest(-l.signed_amount,0) amount_out,sum(l.signed_amount) over(order by l.occurred_at,l.id) balance,l.receiver_name,coalesce(e.full_name,u.email,'System') recorded_by from public.crew_cash_ledger_entries l left join public.employees e on e.id=l.recorded_by_employee_id left join auth.users u on u.id=l.recorded_by_user_id where l.outlet_id=p_outlet_id) select coalesce(jsonb_agg(to_jsonb(x) order by x.occurred_at desc,x.id desc),'[]'::jsonb) into v_rows from (select * from ledger where timezone('Asia/Kuala_Lumpur',occurred_at)::date between p_from and p_to order by occurred_at desc,id desc offset (v_page-1)*v_size limit v_size)x;
 end if;
 return jsonb_build_object('rows',v_rows,'total_count',v_total,'page',v_page,'page_size',v_size,'summary',v_summary,'settings',v_settings,'collections',v_collections);
end; $$;
revoke all on function public.crew_cash_admin_page(uuid,date,date,text,integer,integer) from public,anon,authenticated;
grant execute on function public.crew_cash_admin_page(uuid,date,date,text,integer,integer) to authenticated;

create or replace function public.crew_cash_admin_context(p_outlet_id uuid)
returns jsonb language plpgsql stable security definer set search_path=public as $$
declare v_settings jsonb; v_employees jsonb; v_receivers jsonb; v_positions jsonb; v_history jsonb;
begin
 if not ((public.current_user_has_permission('crew_cash_checkout.view') or public.current_user_has_permission('crew_cash_deposit.view')) and public.current_user_can_access_outlet(p_outlet_id)) then raise exception using errcode='42501',message='Cash Checkout access is unavailable for this outlet.'; end if;
 select coalesce(to_jsonb(s),'{}'::jsonb) into v_settings from public.crew_cash_settings s where s.outlet_id=p_outlet_id;
 select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'name',e.full_name,'position',e.position) order by e.full_name),'[]'::jsonb) into v_employees from public.employees e join public.crew_access ca on ca.employee_id=e.id where ca.primary_outlet_id=p_outlet_id and ca.access_state='active' and e.is_active and coalesce(e.employment_status,'active') not in ('resigned','terminated');
 select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'name',e.full_name,'position',e.position) order by e.full_name),'[]'::jsonb) into v_receivers from public.crew_cash_handover_receivers r join public.employees e on e.id=r.employee_id where r.outlet_id=p_outlet_id and public.crew_cash_receiver_is_eligible(p_outlet_id,e.id);
 select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'name',p.name,'status',p.status) order by p.name),'[]'::jsonb) into v_positions from public.job_positions p where p.status='active' or p.id=any(coalesce((select required_position_ids from public.crew_cash_settings where outlet_id=p_outlet_id),'{}'::uuid[]));
 select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'previous_amount',a.previous_amount,'new_amount',a.new_amount,'effective_date',a.effective_date,'reason',a.reason,'adjusted_at',a.adjusted_at,'adjusted_by',coalesce(u.email,'Admin')) order by a.effective_date desc,a.adjusted_at desc),'[]'::jsonb) into v_history from public.crew_cash_float_adjustments a left join auth.users u on u.id=a.adjusted_by where a.outlet_id=p_outlet_id;
 return jsonb_build_object('settings',v_settings,'employees',v_employees,'eligible_receivers',v_receivers,'checkout_positions',v_positions,'float_history',v_history,'receiver_configuration',coalesce((select jsonb_build_object('version',c.version,'updated_at',c.updated_at) from public.crew_cash_handover_receiver_configs c where c.outlet_id=p_outlet_id),'{}'::jsonb));
end; $$;
revoke all on function public.crew_cash_admin_context(uuid) from public,anon,authenticated;
grant execute on function public.crew_cash_admin_context(uuid) to authenticated;

create or replace function public.crew_tasks_admin_page(p_outlet_id uuid,p_from date,p_to date,p_listing text default 'definitions',p_filters jsonb default '{}'::jsonb,p_page integer default 1,p_page_size integer default 20)
returns jsonb language plpgsql volatile security definer set search_path=public as $$
declare v_page integer:=greatest(coalesce(p_page,1),1); v_size integer:=case when p_page_size in(20,50,100) then p_page_size else 20 end; v_total integer; v_rows jsonb; v_sops jsonb; v_employees jsonb; v_summary jsonb;
begin
 if not public.current_user_has_permission('crew_operations.view') or not public.current_user_can_access_outlet(p_outlet_id) then raise exception using errcode='42501',message='Tasks are unavailable for this outlet.'; end if;
 if p_from is null or p_to is null or p_from>p_to or p_to-p_from>92 then raise exception using errcode='22023',message='Choose a valid Task period of 93 days or fewer.'; end if;
 if p_listing not in ('definitions','review_queue') then raise exception using errcode='22023',message='Unsupported Tasks listing.'; end if;
 perform public.crew_tasks_refresh_lifecycle(p_outlet_id); perform public.crew_operations_ensure_instances(p_outlet_id,d::date) from generate_series(p_from,p_to,interval '1 day') g(d);
 select coalesce(jsonb_agg(jsonb_build_object('sop_id',s.id,'title',s.title,'version_id',v.id,'version',v.version) order by s.title),'[]'::jsonb) into v_sops from public.crew_sops s join lateral(select * from public.crew_sop_versions v where v.sop_id=s.id and v.status='published' order by v.version desc limit 1)v on true where s.outlet_id is null or s.outlet_id=p_outlet_id;
 select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'name',e.full_name,'position',e.position) order by e.full_name),'[]'::jsonb) into v_employees from public.employees e join public.crew_access ca on ca.employee_id=e.id and ca.primary_outlet_id=p_outlet_id and ca.access_state='active' where e.is_active and coalesce(e.employment_status,'active') not in ('resigned','terminated');
 if p_listing='review_queue' then
  select count(*) into v_total from public.crew_task_instance_assignees a join public.crew_operation_instances i on i.id=a.instance_id where i.outlet_id=p_outlet_id and i.business_date between p_from and p_to and a.status='review_required';
  select coalesce(jsonb_agg(to_jsonb(x) order by x.business_date,x.employee_name),'[]'::jsonb) into v_rows from (select i.id instance_id,e.id employee_id,i.name task_name,e.full_name employee_name,i.business_date,a.status from public.crew_task_instance_assignees a join public.crew_operation_instances i on i.id=a.instance_id join public.employees e on e.id=a.employee_id where i.outlet_id=p_outlet_id and i.business_date between p_from and p_to and a.status='review_required' order by i.business_date,e.full_name offset (v_page-1)*v_size limit v_size)x;
 else
  with series as (select t.series_id,max(t.updated_at) updated_at from public.crew_operation_templates t where t.outlet_id=p_outlet_id group by t.series_id), canonical as (select s.*,coalesce((select t.id from public.crew_operation_templates t where t.series_id=s.series_id and t.status<>'draft' order by case t.status when 'active' then 1 when 'paused' then 2 when 'ended' then 3 else 4 end,t.revision desc limit 1),(select t.id from public.crew_operation_templates t where t.series_id=s.series_id and t.status='draft' order by t.revision desc limit 1)) template_id from series s), filtered as (select t.* from canonical c join public.crew_operation_templates t on t.id=c.template_id where (coalesce(p_filters->>'status','all')='all' or t.status=p_filters->>'status') and (coalesce(p_filters->>'assignment','all')='all' or t.assignment_type=p_filters->>'assignment') and (coalesce(p_filters->>'query','')='' or concat_ws(' ',t.name,t.task_type,t.assignment_type) ilike '%'||p_filters->>'query'||'%')) select count(*) into v_total from filtered;
  with series as (select t.series_id,max(t.updated_at) updated_at from public.crew_operation_templates t where t.outlet_id=p_outlet_id group by t.series_id), canonical as (select s.*,coalesce((select t.id from public.crew_operation_templates t where t.series_id=s.series_id and t.status<>'draft' order by case t.status when 'active' then 1 when 'paused' then 2 when 'ended' then 3 else 4 end,t.revision desc limit 1),(select t.id from public.crew_operation_templates t where t.series_id=s.series_id and t.status='draft' order by t.revision desc limit 1)) template_id from series s), filtered as (select t.*,c.updated_at series_updated_at from canonical c join public.crew_operation_templates t on t.id=c.template_id where (coalesce(p_filters->>'status','all')='all' or t.status=p_filters->>'status') and (coalesce(p_filters->>'assignment','all')='all' or t.assignment_type=p_filters->>'assignment') and (coalesce(p_filters->>'query','')='' or concat_ws(' ',t.name,t.task_type,t.assignment_type) ilike '%'||p_filters->>'query'||'%')) select coalesce(jsonb_agg((to_jsonb(x)-'created_by')||jsonb_build_object('definition_status',x.status,'next_run',public.crew_tasks_next_run(x),'has_draft',exists(select 1 from public.crew_operation_templates d where d.series_id=x.series_id and d.status='draft'),'blocks',coalesce((select jsonb_agg((to_jsonb(i)-'sop_snapshot')||jsonb_build_object('sop_reference',i.sop_snapshot,'config',i.block_config) order by i.sort_order) from public.crew_operation_template_items i where i.template_id=x.id),'[]'::jsonb)) order by x.series_updated_at desc),'[]'::jsonb) into v_rows from (select * from filtered order by series_updated_at desc,id desc offset (v_page-1)*v_size limit v_size)x;
 end if;
 select jsonb_build_object('published_sops',v_sops,'employees',v_employees,'from',p_from,'to',p_to) into v_summary;
 return jsonb_build_object('rows',v_rows,'total_count',v_total,'page',v_page,'page_size',v_size,'summary',v_summary);
end; $$;
revoke all on function public.crew_tasks_admin_page(uuid,date,date,text,jsonb,integer,integer) from public,anon,authenticated;
grant execute on function public.crew_tasks_admin_page(uuid,date,date,text,jsonb,integer,integer) to authenticated;

create or replace function public.crew_feedback_admin_page(p_outlet_id uuid,p_period date,p_filters jsonb default '{}'::jsonb,p_page integer default 1,p_page_size integer default 20)
returns jsonb language plpgsql stable security definer set search_path=public as $$
declare v_period date:=date_trunc('month',p_period)::date; v_page integer:=greatest(coalesce(p_page,1),1); v_size integer:=case when p_page_size in(20,50,100) then p_page_size else 20 end; v_total integer; v_rows jsonb; v_summary jsonb; v_crew jsonb; v_follow_up boolean:=public.current_user_has_permission('crew_feedback.follow_up.view');
begin
 if not public.current_user_has_permission('crew_feedback.view') or not public.current_user_can_access_outlet(p_outlet_id) then raise exception using errcode='42501',message='Customer Feedback is unavailable for this outlet.'; end if;
 select jsonb_build_object('total_feedback',count(*),'crew_feedback',count(*) filter(where scope='crew'),'food_feedback',count(*) filter(where scope='food'),'outlet_feedback',count(*) filter(where scope='outlet'),'included_feedback',count(*) filter(where scope='crew' and scoring_status='included' and trust_state in ('standard','confirmed')),'review_required_feedback',count(*) filter(where scope='crew' and trust_state='review_required'),'positive_feedback',count(*) filter(where experience='great'),'needs_improvement_feedback',count(*) filter(where experience='needs_improvement'),'excluded_feedback',count(*) filter(where scope='crew' and scoring_status='excluded')) into v_summary from public.crew_customer_feedback where outlet_id=p_outlet_id and submitted_at>=v_period and submitted_at<v_period+interval '1 month';
 with filtered as (select f.* from public.crew_customer_feedback f left join public.employees e on e.id=f.employee_id where f.outlet_id=p_outlet_id and f.submitted_at>=v_period and f.submitted_at<v_period+interval '1 month' and (coalesce(p_filters->>'scope','all')='all' or f.scope=p_filters->>'scope') and (coalesce(p_filters->>'experience','all')='all' or f.experience=p_filters->>'experience') and (coalesce(p_filters->>'status','all')='all' or f.scoring_status=p_filters->>'status') and (coalesce(p_filters->>'trust','all')='all' or f.trust_state=p_filters->>'trust') and (coalesce(p_filters->>'query','')='' or concat_ws(' ',e.full_name,f.comment,array_to_string(f.positive_tags,' '),array_to_string(f.improvement_tags,' ')) ilike '%'||p_filters->>'query'||'%')) select count(*) into v_total from filtered;
 with filtered as (select f.* from public.crew_customer_feedback f left join public.employees e on e.id=f.employee_id where f.outlet_id=p_outlet_id and f.submitted_at>=v_period and f.submitted_at<v_period+interval '1 month' and (coalesce(p_filters->>'scope','all')='all' or f.scope=p_filters->>'scope') and (coalesce(p_filters->>'experience','all')='all' or f.experience=p_filters->>'experience') and (coalesce(p_filters->>'status','all')='all' or f.scoring_status=p_filters->>'status') and (coalesce(p_filters->>'trust','all')='all' or f.trust_state=p_filters->>'trust') and (coalesce(p_filters->>'query','')='' or concat_ws(' ',e.full_name,f.comment,array_to_string(f.positive_tags,' '),array_to_string(f.improvement_tags,' ')) ilike '%'||p_filters->>'query'||'%')) select coalesce(jsonb_agg(jsonb_build_object('id',f.id,'scope',f.scope,'submitted_at',f.submitted_at,'employee_id',f.employee_id,'employee_name',e.full_name,'employee_position',e.position,'experience',f.experience,'positive_tags',f.positive_tags,'improvement_tags',f.improvement_tags,'comment',f.comment,'scoring_status',f.scoring_status,'trust_state',f.trust_state,'trust_reason_codes',f.trust_reason_codes,'visit_at',f.visit_at,'visit_business_date',f.visit_business_date,'follow_up_requested',f.follow_up_requested,'excluded_at',f.excluded_at,'excluded_by_name',coalesce(excluded_employee.full_name,excluded_user.email),'exclusion_reason',f.exclusion_reason,'moderation_history',coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'previous_status',a.previous_status,'next_status',a.next_status,'reason',a.reason,'changed_by',coalesce(actor.full_name,user_actor.email),'changed_at',a.changed_at) order by a.changed_at desc) from public.crew_feedback_moderation_audit a left join public.employees actor on actor.auth_user_id=a.changed_by left join auth.users user_actor on user_actor.id=a.changed_by where a.feedback_id=f.id),'[]'::jsonb),'trust_history',coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'previous_trust_state',a.previous_trust_state,'next_trust_state',a.next_trust_state,'reason_codes',a.reason_codes,'reason',a.reason,'decision_source',a.decision_source,'changed_by',coalesce(actor.full_name,user_actor.email),'changed_at',a.changed_at) order by a.changed_at desc) from public.crew_feedback_trust_audit a left join public.employees actor on actor.auth_user_id=a.changed_by left join auth.users user_actor on user_actor.id=a.changed_by where a.feedback_id=f.id),'[]'::jsonb),'attribution_history',coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'previous_employee_id',a.previous_employee_id,'previous_employee_name',previous_employee.full_name,'next_employee_id',a.next_employee_id,'next_employee_name',next_employee.full_name,'reason',a.reason,'changed_by',coalesce(actor.full_name,user_actor.email),'changed_at',a.changed_at) order by a.changed_at desc) from public.crew_feedback_attribution_audit a join public.employees previous_employee on previous_employee.id=a.previous_employee_id join public.employees next_employee on next_employee.id=a.next_employee_id left join public.employees actor on actor.auth_user_id=a.changed_by left join auth.users user_actor on user_actor.id=a.changed_by where a.feedback_id=f.id),'[]'::jsonb),'follow_up',case when v_follow_up then coalesce((select jsonb_build_object('preferred_name',fu.preferred_name,'contact_method',fu.contact_method,'contact_value',fu.contact_value,'status',fu.status,'created_at',fu.created_at,'resolved_at',fu.resolved_at,'history',coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'previous_status',a.previous_status,'next_status',a.next_status,'changed_by',coalesce(actor.full_name,user_actor.email),'changed_at',a.changed_at) order by a.changed_at desc) from public.crew_feedback_follow_up_audit a left join public.employees actor on actor.auth_user_id=a.changed_by left join auth.users user_actor on user_actor.id=a.changed_by where a.feedback_id=f.id),'[]'::jsonb)) from public.crew_feedback_follow_ups fu where fu.feedback_id=f.id),'null'::jsonb) else 'null'::jsonb end) order by f.submitted_at desc),'[]'::jsonb) into v_rows from (select * from filtered order by submitted_at desc,id desc offset (v_page-1)*v_size limit v_size)f left join public.employees e on e.id=f.employee_id left join public.employees excluded_employee on excluded_employee.auth_user_id=f.excluded_by left join auth.users excluded_user on excluded_user.id=f.excluded_by;
 select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'name',x.full_name,'position',x.position,'availability',x.availability) order by x.full_name),'[]'::jsonb) into v_crew from (select distinct e.id,e.full_name,e.position,case when ca.primary_outlet_id=p_outlet_id and ca.access_state='active' and e.is_active and coalesce(e.employment_status,'active') not in ('resigned','terminated') then 'active' else 'historical' end availability from public.employees e left join public.crew_access ca on ca.employee_id=e.id where (ca.primary_outlet_id=p_outlet_id and ca.access_state='active' and e.is_active and coalesce(e.employment_status,'active') not in ('resigned','terminated')) or exists(select 1 from public.crew_customer_feedback historical where historical.outlet_id=p_outlet_id and historical.scope='crew' and historical.employee_id=e.id))x;
 return jsonb_build_object('rows',v_rows,'total_count',v_total,'page',v_page,'page_size',v_size,'summary',v_summary || jsonb_build_object('feedback_crew',v_crew));
end; $$;
revoke all on function public.crew_feedback_admin_page(uuid,date,jsonb,integer,integer) from public,anon,authenticated;
grant execute on function public.crew_feedback_admin_page(uuid,date,jsonb,integer,integer) to authenticated;
